// 线程A：危险的解锁逻辑
if (uuid.equals(redis.get(key))) {
    // 此时锁过期，线程B加锁成功
    // 线程A执行删除，导致B的锁被误删
    redis.del(key); 
}

// Lua脚本解锁
String script = 
  "if redis.call('get', KEYS[1]) == ARGV[1] " +
  "then return redis.call('del', KEYS[1]) " +
  "else return 0 end";
redis.eval(script, key, uuid);

// 点赞与共同关注示例
SADD like:post:1001 user:88
SISMEMBER like:post:1001 user:88
// 计算用户A与用户B的共同关注
SINTER user:A:following user:B:following

// 推送最新动态
ZADD user:888:timeline 1704067200 'post:1001'
// 获取最新10条动态
ZREVRANGE user:888:timeline 0 9 WITHSCORES
